            if market:
                self.seeder.graph.add_node(market, "market", verified=True)
        if product:
            self.seeder.graph.add_node(product, "product", verified=True)

    for f in flows:
        reg = f.get("regulation", "")
        if reg:
            self.seeder.graph.add_node(reg, "regulation", verified=True)

def judge_hypotheses(self) -> list[dict]:
    """Judge which hypotheses survived based on graph evidence.
    Returns list of hypothesis verdicts.
    """
    confirmed = self.seeder.graph.confirmed_hypotheses()
    untested = self.seeder.graph.untested_hypotheses()
    return [
        {"id": h, "verdict": "confirmed"} for h in confirmed
    ] + [
        {"id": h, "verdict": "untested"} for h in untested
    ]

